'use strict';

/**
* Extract property values from an input object array and assign results to elements in a new output array.
*
* @module @stdlib/array/base/pluck
*
* @example
* var pluck = require( '@stdlib/array/base/pluck' );
*
* var x = [
*     {
*         'a': 1
*     },
*     {
*         'a': 2
*     },
*     {
*         'a': 3
*     }
* ];
*
* var out = pluck( x, 'a' );
* // returns [ 1, 2, 3 ]
*
* @example
* var pluck = require( '@stdlib/array/base/pluck' );
*
* var x = [
*     {
*         'a': 1
*     },
*     {
*         'a': 2
*     },
*     {
*         'a': 3
*     }
* ];
*
* var y = [ 0, 0, 0 ];
* var out = pluck.assign( x, 'a', out, 1, 0 );
* // returns [ 1, 2, 3 ]
*
* var bool = ( out === y );
* returns true
*/

// MODULES //

var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var main = require( './main.js' );
var assign = require( './assign.js' );


// MAIN //

setReadOnly( main, 'assign', assign );


// EXPORTS //

module.exports = main;
